package loja.checkout;

import java.math.BigDecimal;
import java.util.Arrays;
import java.util.Optional;

public enum Regiao {
    SUDESTE("0.01"), SUL("0.01"), CENTRO_OESTE("0.015"), NORTE("0.025"), NORDESTE("0.02");

